discover_netcdf_files <- function(path) { ext <- tolower(tools::file_ext(path)); if(ext %in% c("nc","nc4")) return(path); if(ext=="zip") { z <- unzip(path,list=TRUE)$Name; return(file.path(dirname(path),z[grepl("\\.nc4?$",z,ignore.case=TRUE)])) }; character() }
normalize_downloaded_file <- function(path, extraction_dir) { if(!file.exists(path)) stop("Raw file missing: ",path); fs::dir_create(extraction_dir,recurse=TRUE); if(tolower(tools::file_ext(path))=="zip") { z <- unzip(path,list=TRUE)$Name; if(any(grepl("(^|/|\\\\)\\.\\.|(^|/|\\\\)\\.",z))) stop("Unsafe archive paths"); unzip(path,exdir=extraction_dir); discover_netcdf_files(file.path(extraction_dir,basename(path))) } else discover_netcdf_files(path) }
inspect_netcdf_file <- function(path) { if(!requireNamespace("terra",quietly=TRUE)) stop("terra is required"); r <- terra::rast(path); list(path=path, variables=names(r), dimensions=c(ncol=terra::ncol(r),nrow=terra::nrow(r),layers=terra::nlyr(r)), crs=terra::crs(r), extent=as.vector(terra::ext(r)), resolution=terra::res(r), time=terra::time(r)) }
